using System;using System.Collections.Generic;using System.Web.Script.Serialization;
internal static class UsbAdmissionTabModelTest {
 static void Check(bool ok){if(!ok)throw new Exception("Tab model regression");}
 static UsbAdmissionInventory.Subject Subject(string id,string parent,string name){return new UsbAdmissionInventory.Subject{DisplayName=name,Input=new UsbAdmissionPreflight.Input{Instance=id,ParentChain=new[]{id,parent,@"USB\ROOT_HUB30\SYNTHETIC",@"HTREE\ROOT\0"}}};}
 public static int Main(){string parent=@"USB\VID_0000&PID_0000\SHARED",one=@"USB\VID_0000&PID_0000&MI_00\ONE",two=@"USB\VID_0000&PID_0000&MI_01\TWO",builtIn=@"USB\VID_1111&PID_1111\INTERNAL";var inventory=new UsbAdmissionInventory.Result{Complete=true,Preflight=new UsbAdmissionPreflight.Result{State="review_required",TopologyToken=new string('c',64),Candidates=new[]{new UsbAdmissionPreflight.Candidate{Instance=one,Category="external_approval_required"},new UsbAdmissionPreflight.Candidate{Instance=two,Category="external_approval_required"},new UsbAdmissionPreflight.Candidate{Instance=builtIn,Category="required_safety_candidate"}}},Subjects=new[]{Subject(one,parent,"External keyboard"),Subject(two,parent,"External keyboard"),Subject(builtIn,builtIn,"Internal")}};var groups=UsbAdmissionTabModel.Groups(inventory);Check(groups.Count==1&&groups[parent].Count==2);string salt=new string('a',32);Check(UsbAdmissionTabModel.Reference(salt,parent)==UsbAdmissionTabModel.Reference(salt,parent));Check(UsbAdmissionTabModel.Reference(salt,parent)!=UsbAdmissionTabModel.Reference(new string('b',32),parent));var serializer=new JavaScriptSerializer();string json=serializer.Serialize(UsbAdmissionTabModel.Snapshot(inventory,salt));Check(!json.Contains("VID_")&&!json.Contains("SHARED")&&!json.Contains("INTERNAL"));var snapshot=serializer.Deserialize<Dictionary<string,object>>(json);Check((int)snapshot["schemaVersion"]==1&&!(bool)snapshot["verified"]&&!(bool)snapshot["active"]&&snapshot["deadline"]==null);Check(json.Contains("\"canChange\":true")&&json.Contains("\"access\":\"unverified\""));inventory.Complete=false;json=serializer.Serialize(UsbAdmissionTabModel.Snapshot(inventory,salt));Check(json.Contains("\"topology\":null")&&json.Contains("\"canChange\":false")&&!json.Contains("\"access\":\"restricted\""));Check(UsbAdmissionTabModel.Groups(null).Count==0);Console.WriteLine("PASS external-only physical grouping, session-bound refs, no native ID disclosure and truthful incomplete snapshots");return 0;}
}
